var i=[{title:`Începe cu o repetiție ușoară`,text:`Fă mișcarea fără greutate sau cu cel mai ușor accesoriu pe care îl ai. Adaugă o sarcină mică pentru o serie de încălzire și verifică dacă amplitudinea, respirația și ritmul rămân constante. Fiecare mișcare are propria greutate de lucru: o sarcină care pare confortabilă pentru un ramat poate fi mult prea grea pentru o ridicare laterală.`},{title:`Repetări în rezervă`,text:`Repetările în rezervă (RIR) arată câte repetări în plus, cu formă bună, crezi că ai mai putea face. Pentru antrenamentul general, terminarea multor serii cu aproximativ două sau trei repetări rămase este un punct de plecare practic, deși nu trebuie să o faci de fiecare dată. Dacă la o serie planificată de 10 ai simți că ai mai putea face încă 10, sarcina poate fi prea ușoară pentru obiectivul tău.`},{title:`Ajustează în timpul sesiunii`,text:`Să spunem că planul cere trei serii de opt până la douăsprezece. Dacă prima serie se termină la opt cu tehnică șovăielnică și fără nimic în rezervă, scade sarcina. Dacă douăsprezece repetări sunt line și încă destul de ușoare, încearcă o mică creștere la seria următoare. Odihnește-te destul cât să-ți dai seama dacă problema a fost greutatea sau oboseala.`},{title:`Când salturile de greutate sunt prea mari`,text:`Dacă următoarea ganteră este prea grea, adaugă o repetare, o pauză controlată sau încă o serie bună. Dacă și cea mai ușoară greutate a ta este prea grea, folosește greutatea corpului, o bandă elastică sau o altă pârghie. Nu forța niciodată repetări ratate ca să atingi un număr stabilit.`},{title:`Folosirea TrainUp`,text:`Planul tău dă serii, repetări și odihnă, dar fără greutăți, așa că tu alegi sarcina. În timpul antrenamentului, notează repetările pe care le-ai făcut de fapt, iar după el evaluează efortul sesiunii de la 1 la 10. Dacă simți durere, ți se face amețeală sau îți pierzi mereu tehnica, oprește-te sau schimbă exercițiul; nu adăuga rezistență. „Simt durere” încheie imediat exercițiul curent.`}];var r=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Rezumatul ghidului ACSM 2026 pentru antrenamentul de forță`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`Mayo Clinic: siguranța și tehnica antrenamentului cu greutăți`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};